        for col in range(cols - 1):
            data["key" + str(col + 1)] = IMPL.Index(
                [f"i-{i}" for i in range(N)], dtype=object
            ).values.repeat(K)
        data["value"] = np.random.randn(N * K)
        self.df = IMPL.DataFrame(data)
        execute(self.df)'}

