        index = IMPL.MultiIndex.from_product(
            [df.index[: shape[0] // 2], ["bar", "foo"]]
        )
        columns = IMPL.MultiIndex.from_product(
            [df.columns[: shape[1] // 2], ["buz", "fuz"]]
        )

        df.index = index
        df.columns = columns

        self.df = df.sort_index(axis=1)'}

