    def setup(self, shape, item_length, loc, is_equal_indices):
        self.df = generate_dataframe("int", *shape, RAND_LOW, RAND_HIGH).copy()
        self.loc, self.iloc = self.get_loc(
            self.df, loc, item_length=item_length, axis=1
