{'unit_benchmarks.TimeCreateExpression.time_create_expression': 'class TimeCreateExpression:
    def time_create_expression(self):
        self.R = pybamm.Parameter("Particle radius [m]")
        D = pybamm.Parameter("Diffusion coefficient [m2.s-1]")
        j = pybamm.Parameter("Interfacial current density [A.m-2]")
        F = pybamm.Parameter("Faraday constant [C.mol-1]")
        c0 = pybamm.Parameter("Initial concentration [mol.m-3]")
        self.model = pybamm.BaseModel()

        c = pybamm.Variable("Concentration [mol.m-3]", domain="negative particle")
        N = -D * pybamm.grad(c)
        dcdt = -pybamm.div(N)
        self.model.rhs = {c: dcdt}

        lbc = pybamm.Scalar(0)
        rbc = -j / F / D
        self.model.boundary_conditions = {
            c: {"left": (lbc, "Neumann"), "right": (rbc, "Neumann")}
        }

        self.model.initial_conditions = {c: c0}
        self.model.variables = {
            "Concentration [mol.m-3]": c,
            "Surface concentration [mol.m-3]": pybamm.surf(c),
            "Flux [mol.m-2.s-1]": N,
        }

    def setup(self):
        set_random_seed()', 'unit_benchmarks.TimeDiscretiseModel.time_create_expression': 'class TimeCreateExpression:
