{'qasm3_exporter.CustomGateBenchmarks.time_dumps': 'class CustomGateBenchmarks:
    def time_dumps(self, _, __):
        qasm3.dumps(self.circuit)

    def setup(self, n_qubits, depth):
        custom_gate = QuantumCircuit(2, name="custom_gate")
        custom_gate.h(0)
        custom_gate.x(1)

        qc = QuantumCircuit(n_qubits)
        for _ in range(depth):
            for i in range(n_qubits - 1):
                qc.append(custom_gate.to_gate(), [i, i + 1])
        self.circuit = qc', 'qasm3_exporter.ParameterizedBenchmarks.time_dumps': 'class ParameterizedBenchmarks:
    def time_dumps(self, _, __):
        qasm3.dumps(self.circuit)

    def setup(self, n_qubits, n_params):
        qc = QuantumCircuit(n_qubits)
        params = [Parameter(f"angle{i}") for i in range(n_params)]
        for n in range(n_qubits - 1):
            for i in params:
                qc.rx(i, n)
        self.circuit = qc', 'qasm3_exporter.RandomBenchmarks.time_dumps': 'class RandomBenchmarks:
    def time_dumps(self, _, __, ___):
        qasm3.dumps(self.circuit)

    def setup(self, n_qubits, depth, seed):
        self.circuit = random_circuit(
            n_qubits,
            depth,
            measure=True,
            conditional=True,
            reset=True,
            seed=seed,
            max_operands=3,
        )'}

