            measure=True,
            conditional=True,
            reset=True,
            seed=seed,
            max_operands=3,
        )'}

{'qft.LargeQFTMappingTimeBench.time_sabre_swap': 'class LargeQFTMappingTimeBench:
    def time_sabre_swap(self, _n_qubits, heuristic):
        pass_ = SabreSwap(self.coupling, heuristic, seed=2022_10_27, trials=1)
        pass_.run(self.dag)

    def setup(self, n_qubits, _heuristic):
        qr = QuantumRegister(n_qubits, name="q")
        self.dag = circuit_to_dag(build_model_circuit(qr))
        self.coupling = CouplingMap.from_heavy_hex(self.heavy_hex_size[n_qubits])'}

{'quantum_info.CliffordComposeBench.time_compose': 'class CliffordComposeBench:
    def time_compose(self, nqubits_length):
        (nqubits, length) = map(int, nqubits_length.split(","))
        clifford = Clifford(np.eye(2 * nqubits))
        for i in range(length):
            clifford.compose(self.random_clifford[i])

    def setup(self, nqubits_length):
        (nqubits, length) = map(int, nqubits_length.split(","))
        self.random_clifford = [random_clifford(nqubits) for _ in range(length)]'}

