{'qft.LargeQFTMappingTimeBench.time_sabre_swap': 'class LargeQFTMappingTimeBench:
    def time_sabre_swap(self, _n_qubits, heuristic):
        pass_ = SabreSwap(self.coupling, heuristic, seed=2022_10_27, trials=1)
        pass_.run(self.dag)

