                benchmark::DoNotOptimize(&hasTrait);
            };
        }
        ```
        """
        Extensibility.OP_WITH_REGION.has_trait(TraitB)', 'microbenchmarks.Extensibility.time_trait_check_optimised': 'class Extensibility:
    def time_trait_check_optimised(self) -> None:
        """Time checking the trait of an operation using optimised code."""
        OP = Extensibility.OP_WITH_REGION
