{'qasm3_exporter.ParameterizedBenchmarks.time_dumps': 'class ParameterizedBenchmarks:
    def time_dumps(self, _, __):
        qasm3.dumps(self.circuit)

    def setup(self, n_qubits, n_params):
        qc = QuantumCircuit(n_qubits)
        params = [Parameter(f"angle{i}") for i in range(n_params)]
        for n in range(n_qubits - 1):
            for i in params:
                qc.rx(i, n)
        self.circuit = qc', 'qasm3_exporter.RandomBenchmarks.time_dumps': 'class RandomBenchmarks:
    def time_dumps(self, _, __, ___):
        qasm3.dumps(self.circuit)

    def setup(self, n_qubits, depth, seed):
        self.circuit = random_circuit(
            n_qubits,
            depth,
            measure=True,
            conditional=True,
            reset=True,
            seed=seed,
            max_operands=3,
        )'}

{'quantum_info.CliffordComposeBench.time_compose': 'class CliffordComposeBench:
    def time_compose(self, nqubits_length):
        (nqubits, length) = map(int, nqubits_length.split(","))
        clifford = Clifford(np.eye(2 * nqubits))
        for i in range(length):
            clifford.compose(self.random_clifford[i])

    def setup(self, nqubits_length):
        (nqubits, length) = map(int, nqubits_length.split(","))
        self.random_clifford = [random_clifford(nqubits) for _ in range(length)]', 'quantum_info.PauliBench.time_evolve': 'class PauliBench:
    def time_evolve(self, _):
        self.p1.evolve(self.p2)  # by another Pauli, so by composition

    def setup(self, num_qubits):
        self.p1 = random_pauli(num_qubits, True)
        self.p2 = random_pauli(num_qubits, True)', 'quantum_info.PauliListBench.time_group_qubit_wise_commuting': 'class PauliListBench:
    def time_group_qubit_wise_commuting(self, _, __):
        self.pl1.group_qubit_wise_commuting()  # exercise retworkx-based code

    def setup(self, num_qubits, length):
        self.pl1 = random_pauli_list(num_qubits=num_qubits, size=length, phase=True)
        self.pl2 = random_pauli_list(num_qubits=num_qubits, size=length, phase=True)', 'quantum_info.SparsePauliOpBench.time_simplify': 'class SparsePauliOpBench:
