            raise NotImplementedError
        self.circuit, self.params = build_parameterized_circuit(width, gates, params)', 'circuit_construction.ParameterizedCircuitConstructionBench.time_build_parameterized_circuit': 'class ParameterizedCircuitConstructionBench:
